<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'; import QRCode from 'qrcode'; import { useProfileStore } from '../stores/profile'; import { platforms,platformById,normalizeUrl } from '../platforms'; import type { PlatformType } from '../types'; import ProfilePreview from '../components/ProfilePreview.vue'; import ImageCropper from '../components/ImageCropper.vue'
const store=useProfileStore(),tab=ref<'profile'|'links'|'design'|'share'>('profile'),cropSrc=ref(''),showAdd=ref(false),qr=ref(''); const publicUrl=computed(()=>`${location.origin}/u/${store.profile.slug}`)
const panelTitle=computed(()=>tab.value==='share'?'Share & QR':tab.value.charAt(0).toUpperCase()+tab.value.slice(1)); function copyLink(){void window.navigator.clipboard.writeText(publicUrl.value)}
onMounted(async()=>{await store.restore();await makeQr()}); async function makeQr(){qr.value=await QRCode.toDataURL(publicUrl.value,{width:640,margin:2})}
function upload(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>cropSrc.value=String(r.result);r.readAsDataURL(f)}
async function publish(){await store.publish();await makeQr();tab.value='share'} function add(p:PlatformType){store.addLink(p,platformById(p).name);showAdd.value=false} function download(ext:'png'|'svg'){if(ext==='png'){const a=document.createElement('a');a.href=qr.value;a.download=`${store.profile.slug}-qr.png`;a.click()}else QRCode.toString(publicUrl.value,{type:'svg'},(_,svg)=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));a.download=`${store.profile.slug}-qr.svg`;a.click()})}
</script>
<template><div class="dashboard"><header><a class="wordmark" href="/">✳ <b>LinkCard</b></a><div class="save-status"><i></i>{{store.saveState}}</div><div><a class="preview-link" :href="`/u/${store.profile.slug}`" target="_blank">Preview ↗</a><button class="publish" @click="publish">{{store.profile.published?'Update':'Publish'}}</button></div></header><main><aside><button v-for="item in [['profile','▣','Profile'],['links','⌁','Links'],['design','✦','Design'],['share','▦','Share & QR']]" :key="item[0]" :class="{active:tab===item[0]}" @click="tab=item[0] as any"><i>{{item[1]}}</i><span>{{item[2]}}</span></button></aside><section class="control-panel">
  <div class="panel-top"><small>PROFILE EDITOR</small><h1>{{panelTitle}}</h1></div>
  <div v-if="tab==='profile'" class="controls"><label class="editor-photo"><img v-if="store.profile.imageUrl" :src="store.profile.imageUrl"><span v-else>＋</span><input type="file" accept="image/*" @change="upload"><b>Change profile photo</b></label><label>Display name<input v-model="store.profile.displayName" @change="store.save"></label><label>Title<input v-model="store.profile.title" @change="store.save"></label><label>Bio<textarea v-model="store.profile.bio" @change="store.save"></textarea></label><label>Image description<input v-model="store.profile.imageAlt" @change="store.save"></label><label>Public username<div class="input-prefix"><span>/u/</span><input v-model="store.profile.slug" @change="store.save"></div></label></div>
  <div v-else-if="tab==='links'" class="controls"><p class="hint">Use the arrows to place your most important links first.</p><article v-for="(link,i) in store.profile.links" :key="link.id" class="link-card"><div class="link-card-top"><i :style="{background:platformById(link.platform).color}">{{platformById(link.platform).icon}}</i><input v-model="link.label" @change="store.save"><label class="switch"><input v-model="link.enabled" type="checkbox" @change="store.save"><span></span></label></div><input v-model="link.url" placeholder="https://" @change="link.url=normalizeUrl(link.url);store.save()"><div class="link-actions"><button :disabled="i===0" @click="store.moveLink(i,-1)">↑</button><button :disabled="i===store.profile.links.length-1" @click="store.moveLink(i,1)">↓</button><button @click="store.removeLink(link.id)">Delete</button></div></article><button class="add-link" @click="showAdd=true">＋ Add a link</button></div>
  <div v-else-if="tab==='design'" class="controls design-controls"><h3>Header layout</h3><div class="choice-grid"><button v-for="v in ['classic','hero','banner','cutout','shape']" :class="{active:store.profile.theme.headerLayout===v}" @click="store.profile.theme.headerLayout=v as any;store.save()">{{v}}</button></div><h3>Wallpaper</h3><div class="choice-grid"><button v-for="v in ['solid','gradient','image']" :class="{active:store.profile.theme.wallpaperType===v}" @click="store.profile.theme.wallpaperType=v as any;store.save()">{{v}}</button></div><div class="color-pair"><label>Background<input v-model="store.profile.theme.background" type="color" @input="store.save"></label><label v-if="store.profile.theme.wallpaperType==='gradient'">Gradient end<input v-model="store.profile.theme.backgroundEnd" type="color" @input="store.save"></label></div><label v-if="store.profile.theme.wallpaperType==='image'">Wallpaper URL<input v-model="store.profile.theme.wallpaperImage" placeholder="https://" @change="store.save"></label><h3>Typography & buttons</h3><label>Font<select v-model="store.profile.theme.font" @change="store.save"><option>DM Sans</option><option>Manrope</option><option>Georgia</option><option>Arial</option><option>Courier New</option></select></label><div class="color-pair"><label>Text<input v-model="store.profile.theme.textColor" type="color" @input="store.save"></label><label>Button<input v-model="store.profile.theme.buttonColor" type="color" @input="store.save"></label></div><div class="choice-grid"><button v-for="v in ['filled','outline','soft']" :class="{active:store.profile.theme.buttonStyle===v}" @click="store.profile.theme.buttonStyle=v as any;store.save()">{{v}}</button></div><div class="choice-grid"><button v-for="v in ['square','rounded','pill']" :class="{active:store.profile.theme.buttonShape===v}" @click="store.profile.theme.buttonShape=v as any;store.save()">{{v}}</button></div><label class="check"><input v-model="store.profile.theme.buttonShadow" type="checkbox" @change="store.save"> Button shadow</label></div>
  <div v-else class="controls share-controls"><div class="published-badge">{{store.profile.published?'● Published':'○ Draft'}}</div><div class="qr-card"><img v-if="qr" :src="qr" alt="Profile QR code"><h2>Ready to share</h2><p>{{publicUrl}}</p></div><div class="share-actions"><button @click="copyLink">Copy link</button><button @click="download('png')">Download PNG</button><button @click="download('svg')">Download SVG</button></div><a :href="publicUrl" target="_blank" class="open-profile">Open public profile ↗</a></div>
  </section><section class="preview-panel"><div class="preview-label"><span>LIVE PREVIEW</span><b>Mobile</b></div><div class="device"><ProfilePreview :profile="store.profile" /></div></section></main>
  <div v-if="showAdd" class="modal-backdrop"><div class="add-modal"><div class="modal-title"><h2>Add a link</h2><button @click="showAdd=false">×</button></div><div class="add-platforms"><button v-for="p in platforms" @click="add(p.id)"><i :style="{background:p.color}">{{p.icon}}</i>{{p.name}}</button><button @click="add('custom')"><i>↗</i>Custom link</button></div></div></div><ImageCropper v-if="cropSrc" :src="cropSrc" @cancel="cropSrc=''" @done="v=>{store.profile.imageUrl=v;cropSrc='';store.save()}" />
</div></template>
